package foodchain

import "strings"

var animals = []string{
	"fly",
	"spider",
	"bird",
	"cat",
	"dog",
	"goat",
	"cow",
	"horse",
}

var comments = []string{
	"I don't know why she swallowed the fly. Perhaps she'll die.",
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

// Verse returns the lyrics of verse v (1-based).
func Verse(v int) string {
	var lines []string
	lines = append(lines, "I know an old lady who swallowed a "+animals[v-1]+".")
	lines = append(lines, comments[v-1])
	if v < len(animals) {
		for i := v - 1; i >= 1; i-- {
			line := "She swallowed the " + animals[i] + " to catch the " + animals[i-1] + "."
			if animals[i-1] == "spider" {
				line = "She swallowed the bird to catch the spider that wriggled and jiggled and tickled inside her."
			}
			lines = append(lines, line)
		}
	}
	return strings.Join(lines, "\n")
}

// Verses returns the lyrics of verses start through end, joined by blank lines.
func Verses(start, end int) string {
	var verses []string
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

// Song returns the complete song.
func Song() string {
	return Verses(1, len(animals))
}

